[CmdletBinding()]
param([string]$Root = "C:\Users\adams\OneDrive\Documents\SprintTimerIntegrated")
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
Set-Location -LiteralPath $Root
$Root = (Get-Location).Path
$expected = "278f3b37780076076834889956da9fa68cabde2d"
$exeName = "SprintTimerIntegrated.exe"
$sourceNames = @("Program.cs","Vision.cs","LiveRecovery.cs","Overlay.cs","CaptureDiagnostics.cs","Settings.cs","FocusGuard.cs","Build.ps1")
$assetNames = @("SDL2.dll","icon.png","detector.json","settings.json")
function Assert-Closed {
    if (Get-Process -Name SprintTimerIntegrated -ErrorAction SilentlyContinue) {
        throw "Close SprintTimerIntegrated completely before running this patch."
    }
}
function Assert-Head {
    $head = (& git rev-parse HEAD | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $head -ne $expected) {
        throw "Expected local HEAD $expected. No Git operations will be performed by this script."
    }
}
function Replace-One([string]$Text,[string]$Old,[string]$New) {
    $n = [regex]::Matches($Text,[regex]::Escape($Old)).Count
    if ($n -ne 1) { throw "Expected one patch anchor; found $n : $Old" }
    return $Text.Replace($Old,$New)
}
function Assert-X64([string]$Path) {
    $reader = New-Object IO.BinaryReader([IO.File]::OpenRead($Path))
    try {
        if ($reader.ReadUInt16() -ne 0x5A4D) { throw "Invalid DOS header: $Path" }
        $reader.BaseStream.Position = 0x3C
        $offset = $reader.ReadInt32()
        if ($offset -lt 64 -or $offset + 6 -gt $reader.BaseStream.Length) { throw "Invalid PE offset" }
        $reader.BaseStream.Position = $offset
        if ($reader.ReadUInt32() -ne 0x4550 -or $reader.ReadUInt16() -ne 0x8664) { throw "Expected x64 PE: $Path" }
    } finally { $reader.Dispose() }
}
Assert-Closed
Assert-Head
Write-Host "Local Git status (read-only):"
& git status --short --branch
if ($LASTEXITCODE -ne 0) { throw "Cannot read Git status." }
$original = @{}
$inputNames = @($sourceNames + $assetNames + $exeName)
foreach ($name in $inputNames) {
    $path = Join-Path $Root $name
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "Required file missing: $name" }
    $original[$name] = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
}
foreach ($name in $sourceNames) {
    $committed = (& git rev-parse "$($expected):$name" | Out-String).Trim()
    if ($LASTEXITCODE -ne 0) { throw "Cannot inspect committed $name" }
    $live = (& git hash-object --path=$name -- $name | Out-String).Trim()
    if ($LASTEXITCODE -ne 0 -or $live -ne $committed) {
        throw "$name differs from the committed baseline. Nothing changed."
    }
}
$stage = Join-Path $env:TEMP ("SprintTimer-overlay-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $stage | Out-Null
Write-Host "Temporary stage: $stage"
foreach ($name in ($sourceNames + $assetNames)) {
    Copy-Item -LiteralPath (Join-Path $Root $name) -Destination (Join-Path $stage $name)
}
$utf8 = New-Object Text.UTF8Encoding($false)
$data = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String("")) | ConvertFrom-Json
foreach ($file in $data.patches.PSObject.Properties) {
    $path = Join-Path $stage $file.Name
    $text = [IO.File]::ReadAllText($path).Replace("`r`n","`n")
    foreach ($change in $file.Value) {
        $text = Replace-One $text ([string]$change[0]) ([string]$change[1])
    }
    [IO.File]::WriteAllText($path,$text,$utf8)
}
[IO.File]::WriteAllText((Join-Path $stage "Overlay.cs"),[string]$data.overlay,$utf8)
$program = [IO.File]::ReadAllText((Join-Path $stage "Program.cs"))
if ([regex]::Matches($program,'private const string AppVersion = "0\.2\.16";').Count -ne 1) {
    throw "Patched version check failed. Nothing installed."
}
$tokens = $null; $errors = $null
$null = [Management.Automation.Language.Parser]::ParseFile((Join-Path $stage "Build.ps1"),[ref]$tokens,[ref]$errors)
if ($errors.Count -gt 0) { throw ($errors | Out-String) }
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File (Join-Path $stage "Build.ps1") -Root $stage -NoLaunch
if ($LASTEXITCODE -ne 0) { throw "Staged build failed. Installed files untouched. Stage: $stage" }
$stageExe = Join-Path $stage $exeName
if (-not (Test-Path -LiteralPath $stageExe -PathType Leaf)) { throw "Missing compiled EXE." }
if ((Get-Item -LiteralPath $stageExe).Length -eq 0) { throw "Empty compiled EXE." }
Assert-X64 $stageExe
if (([Diagnostics.FileVersionInfo]::GetVersionInfo($stageExe)).FileVersion -ne "0.2.16.0") {
    throw "Wrong compiled version. Nothing installed."
}
$installNames = @("Program.cs","Vision.cs","Overlay.cs","Settings.cs",$exeName)
$stagedHashes = @{}
foreach ($name in $installNames) {
    $stagedHashes[$name] = (Get-FileHash -LiteralPath (Join-Path $stage $name) -Algorithm SHA256).Hash
}
Assert-Closed
Assert-Head
foreach ($name in $inputNames) {
    if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $original[$name]) {
        throw "$name changed during staging. Nothing installed."
    }
}
$backup = Join-Path $Root ("backup-overlay-v0.2.16-" + (Get-Date -Format yyyyMMdd-HHmmss) + "-" + [guid]::NewGuid().ToString("N").Substring(0,8))
New-Item -ItemType Directory -Path $backup | Out-Null
foreach ($name in $inputNames) {
    $destination = Join-Path $backup $name
    Copy-Item -LiteralPath (Join-Path $Root $name) -Destination $destination
    if ((Get-FileHash -LiteralPath $destination -Algorithm SHA256).Hash -ne $original[$name]) {
        throw "Backup verification failed for $name. Nothing installed."
    }
}
Assert-Closed
foreach ($name in $inputNames) {
    if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $original[$name]) {
        throw "$name changed during backup. Nothing installed."
    }
}
$touched = New-Object 'System.Collections.Generic.List[string]'
try {
    foreach ($name in $installNames) {
        $touched.Add($name)
        Copy-Item -LiteralPath (Join-Path $stage $name) -Destination (Join-Path $Root $name) -Force
        if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $stagedHashes[$name]) {
            throw "Installed file verification failed: $name"
        }
    }
    Assert-X64 (Join-Path $Root $exeName)
    if (([Diagnostics.FileVersionInfo]::GetVersionInfo((Join-Path $Root $exeName))).FileVersion -ne "0.2.16.0") {
        throw "Installed EXE version mismatch."
    }
} catch {
    $failure = $_
    foreach ($name in $touched) {
        try {
            Copy-Item -LiteralPath (Join-Path $backup $name) -Destination (Join-Path $Root $name) -Force
            if ((Get-FileHash -LiteralPath (Join-Path $Root $name) -Algorithm SHA256).Hash -ne $original[$name]) { throw "Restored hash mismatch" }
        } catch { Write-Warning "ROLLBACK FAILED: $name. Recover from $backup. $_" }
    }
    throw $failure
}
Write-Host "BUILD AND INSTALL SUCCEEDED: Sprint Timer v0.2.16 (x64)" -ForegroundColor Green
Write-Host "Verified backup: $backup"
Write-Host "EXE version: $(([Diagnostics.FileVersionInfo]::GetVersionInfo((Join-Path $Root $exeName))).FileVersion)"
Write-Host "EXE SHA256: $((Get-FileHash -LiteralPath (Join-Path $Root $exeName) -Algorithm SHA256).Hash)"
Write-Host "settings.json retained. No commit, push, branch switch, or publication performed."
try {
    Start-Process -FilePath (Join-Path $Root $exeName) -WorkingDirectory $Root -ErrorAction Stop
    Write-Host "Launch requested. Confirm v0.2.16 in the running window."
} catch {
    Write-Warning "Build/install succeeded, but launch failed: $_"
    Write-Host "Launch manually: $(Join-Path $Root $exeName)"
}
